styles:
.b-team {
    container-type: inline-size;
    --team-gap: 1.5em;
}

.b-team__title {
    margin: 0 0 1em;
}

/* A flex or grid box outranks the browser's own [hidden] rule. */
.b-team__nav[hidden],
.b-team__item[hidden] {
    display: none;
}

/* The grid, and what the slider starts from. Up to `--team-columns` across, fewer when a column
   would be narrower than 13em. */
.b-team__track {
    display: grid;
    grid-template-columns: repeat(
        auto-fill,
        minmax(min(100%, max(13em, (100% - (var(--team-columns, 4) - 1) * var(--team-gap)) / var(--team-columns, 4))), 1fr)
    );
    gap: var(--team-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-team__item {
    min-width: 0;
}

.b-team__card {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1em;
    box-sizing: border-box;
    height: 100%;
    margin: 0;
    text-align: center;
}

.b-team__photo,
.b-team__initials {
    flex: none;
    width: 8em;
    height: 8em;
    border-radius: 50%;
}

.b-team__photo {
    object-fit: cover;
}

.b-team__initials {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5em;
    width: 5.33em;
    height: 5.33em;
    font-weight: 600;
    background: color-mix(in srgb, currentColor 10%, transparent);
}

.b-team__body {
    display: flex;
    flex-direction: column;
    gap: 0.5em;
    min-width: 0;
}

.b-team__name {
    margin: 0;
    font-size: 1.125em;
}

.b-team__job {
    margin: 0;
    opacity: 0.7;
}

.b-team__text {
    margin: 0;
}

.b-team__services,
.b-team__socials {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35em 0.75em;
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-team__card .b-team__services,
.b-team__card .b-team__socials {
    justify-content: center;
}

.b-team__services a {
    color: inherit;
}

.b-team__social {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2em;
    min-height: 2em;
    color: inherit;
    opacity: 0.75;
}

.b-team__social:hover,
.b-team__social:focus-visible {
    opacity: 1;
}

.b-team__icon {
    display: block;
    width: 1.25em;
    height: 1.25em;
}

.b-team__network {
    font-size: 0.9em;
    text-decoration: underline;
}

/* A list: the photo on the left, everything else beside it — the layout for biographies and for
   "who does this" on a service's page. */
.b-team[data-team-layout='list'] .b-team__track {
    display: flex;
    flex-direction: column;
}

.b-team[data-team-layout='list'] .b-team__card {
    flex-direction: row;
    align-items: flex-start;
    gap: 1.5em;
    text-align: start;
}

.b-team[data-team-layout='list'] .b-team__photo {
    width: 7em;
    height: 7em;
}

.b-team[data-team-layout='list'] .b-team__initials {
    width: 4.67em;
    height: 4.67em;
}

.b-team[data-team-layout='list'] .b-team__services,
.b-team[data-team-layout='list'] .b-team__socials {
    justify-content: flex-start;
}

@container (max-width: 30em) {
    .b-team[data-team-layout='list'] .b-team__card {
        flex-direction: column;
    }
}

/* A slider is a ribbon that scrolls sideways — without the script, too. */
.b-team[data-team-layout='slider'] .b-team__viewport {
    overflow-x: auto;
    scrollbar-width: thin;
    scroll-snap-type: x mandatory;
}

.b-team[data-team-layout='slider'] .b-team__track {
    display: flex;
}

.b-team[data-team-layout='slider'] .b-team__item {
    flex: 0 0 calc((100% - (var(--team-columns, 4) - 1) * var(--team-gap)) / var(--team-columns, 4));
    scroll-snap-align: start;
}

@container (max-width: 40em) {
    .b-team[data-team-layout='slider'] .b-team__item {
        flex-basis: 70%;
    }
}

.b-team__nav {
    display: flex;
    justify-content: flex-end;
    gap: 0.5em;
    margin-top: 1em;
}

.b-team__arrow {
    width: 2.5em;
    height: 2.5em;
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 50%;
    cursor: pointer;
}

.b-team__arrow:disabled {
    opacity: 0.35;
    cursor: default;
}

script:
const layout = el.dataset.teamLayout || 'grid'
const viewport = el.querySelector('.b-team__viewport')
const track = el.querySelector('.b-team__track')
const still = window.matchMedia('(prefers-reduced-motion: reduce)')
const items = () => Array.from(el.querySelectorAll('.b-team__item'))

if (layout === 'slider' && viewport && track) {
  const nav = el.querySelector('.b-team__nav')
  const arrows = nav ? Array.from(nav.querySelectorAll('.b-team__arrow')) : []
  // Printed hidden: without this script its buttons would do nothing.
  if (nav) nav.hidden = false

  // One person further, measured rather than assumed: the number across changes with the width.
  const step = () => {
    const first = items()[0]
    const gap = parseFloat(getComputedStyle(track).columnGap) || 0
    return first ? first.getBoundingClientRect().width + gap : viewport.clientWidth
  }
  const atEnd = () => viewport.scrollLeft + viewport.clientWidth >= viewport.scrollWidth - 2
  const go = (direction) => {
    const behavior = still.matches ? 'auto' : 'smooth'
    if (direction > 0 && atEnd()) viewport.scrollTo({ left: 0, behavior })
    else viewport.scrollBy({ left: direction * step(), behavior })
  }
  const update = () => {
    for (const arrow of arrows) {
      if (Number(arrow.dataset.teamStep) < 0) arrow.disabled = viewport.scrollLeft <= 1
    }
  }

  for (const arrow of arrows) {
    arrow.addEventListener('click', () => go(Number(arrow.dataset.teamStep) || 1))
  }
  viewport.addEventListener('scroll', update, { passive: true })
  update()

  if (el.dataset.teamAutoplay === 'on' && !still.matches) {
    let paused = false
    el.addEventListener('mouseenter', () => (paused = true))
    el.addEventListener('mouseleave', () => (paused = false))
    el.addEventListener('focusin', () => (paused = true))
    el.addEventListener('focusout', () => (paused = false))
    setInterval(() => {
      if (!paused && !document.hidden) go(1)
    }, 5000)
  }
}
